$(() => {
  const 家前缀 = '三号楼1002';
  const 拖鞋 = '棉拖鞋';
  // 兜底鞋从初始衣柜实际存在的鞋里按优先级选取，保证写进变量的鞋衣柜里真有
  const 兜底鞋优先 = ['帆布鞋', '小白鞋', '黑色乐福鞋'];
  // 仅当用户明确表达与不变量冲突的意图（要求光脚/不穿/拖鞋出门）时才让位；
  // 「换鞋出门」这类与不变量同向的指令不算反向指令
  const 反向指令 = /(光脚|赤脚|不穿|拖鞋)/;

  waitGlobalInitialized('Mvu').then(() => {
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (新变量, 旧变量) => {
      const 最新 = getChatMessages(-1)[0];
      if (!最新 || 最新.role !== 'assistant' || 最新.message_id === 0) return;

      const 位置 = 新变量?.stat_data?.位置?.地点 as string | undefined;
      const 脚部 = 新变量?.stat_data?.穿着?.脚部 as string | undefined;
      if (typeof 位置 !== 'string' || typeof 脚部 !== 'string') return;

      // 闸一：本轮补丁已成功改动 穿着.脚部 → AI 自己处理了鞋袜，让位
      const 旧脚部 = 旧变量?.stat_data?.穿着?.脚部 as string | undefined;
      if (旧脚部 !== undefined && 脚部 !== 旧脚部) return;

      // 闸二：用户消息明确要求光脚/不穿/拖鞋等反向意图 → 让位（用户指令最高）
      const 玩家楼层 = getChatMessages(-2).filter(m => m.role === 'user').at(-1);
      if (玩家楼层 && 反向指令.test(玩家楼层.message)) return;

      const 衣柜 = 新变量?.stat_data?.['$衣柜'] ?? {};
      const 兜底鞋 = 兜底鞋优先.find(k => !!衣柜[k]) ?? '帆布鞋';

      // 家判定放宽：AI 有时会把「三号楼1002（家）」写成「三号楼1002」，按前缀认定
      const 在家 = 位置.startsWith(家前缀);
      if (!在家) {
        // 不变量一：棉拖鞋绝不跨出家门（AI 没换就机器换；光脚可能是玩家指令，不动）
        if (脚部.includes('拖鞋')) _.set(新变量.stat_data, '穿着.脚部', 兜底鞋);
      } else {
        // 不变量二：在家室内默认棉拖鞋（光脚不动；AI 已换棉拖鞋则无事发生）
        if (脚部 !== '无' && !脚部.includes('拖鞋')) _.set(新变量.stat_data, '穿着.脚部', 拖鞋);
      }
    });
  });
});
